function(container, apiUrl, tables) {
  let currentData = [];
  let workers = [];
  let workItems = [];

  // 初期データ読み込み
  async function loadInitialData() {
    try {
      // 作業記録データ
      const workRecords = await window.aivicApi.list(1) || [];
      currentData = workRecords;

      // ユーザー（作業員）データ
      workers = await window.aivicApi.list(0) || [];

      // 作業項目マスタ
      workItems = await window.aivicApi.list(3) || [];

      // セレクトボックスの初期化
      populateWorkerSelect();
      populateWorkItemSelect();

    } catch (error) {
      console.error('初期データ読み込みエラー:', error);
    }
  }

  // 作業員セレクトボックスの設定
  function populateWorkerSelect() {
    const select = container.querySelector('#select-worker');
    select.innerHTML = '';
    workers.forEach(worker => {
      const option = document.createElement('option');
      option.value = worker.id;
      option.textContent = worker.氏名 || worker.ユーザー名 || 'Unknown';
      select.appendChild(option);
    });
  }

  // 作業項目セレクトボックスの設定
  function populateWorkItemSelect() {
    const select = container.querySelector('#select-work-item');
    select.innerHTML = '';
    workItems.forEach(item => {
      const option = document.createElement('option');
      option.value = item.id;
      option.textContent = item.作業項目名 || 'Unknown';
      select.appendChild(option);
    });
  }

  // データフィルタリング
  function filterData() {
    const startDate = container.querySelector('#input-start-date').value;
    const endDate = container.querySelector('#input-end-date').value;
    const location = container.querySelector('#select-location').value;
    const selectedWorkers = Array.from(container.querySelector('#select-worker').selectedOptions).map(opt => opt.value);
    const selectedWorkItems = Array.from(container.querySelector('#select-work-item').selectedOptions).map(opt => opt.value);
    const includeAnomaly = container.querySelector('#check-include-anomaly').checked;
    const includeInterruption = container.querySelector('#check-include-interruption').checked;

    let filtered = [...currentData];

    // 期間フィルタ
    if (startDate) {
      filtered = filtered.filter(record => {
        const workDate = new Date(record.作業日);
        return workDate >= new Date(startDate);
      });
    }
    if (endDate) {
      filtered = filtered.filter(record => {
        const workDate = new Date(record.作業日);
        return workDate <= new Date(endDate);
      });
    }

    // 場所フィルタ
    if (location) {
      filtered = filtered.filter(record => record.作業場所 === location);
    }

    // 作業員フィルタ
    if (selectedWorkers.length > 0) {
      filtered = filtered.filter(record => selectedWorkers.includes(record.作業員ID));
    }

    // 進捗状況フィルタ（中断記録の扱い）
    if (!includeInterruption) {
      filtered = filtered.filter(record => record.進捗状況 !== '中断');
    }

    return filtered;
  }

  // プレビューテーブル更新
  function updatePreview() {
    const filteredData = filterData();
    const tbody = container.querySelector('#preview-tbody');
    const countElement = container.querySelector('#data-count');

    countElement.textContent = `対象件数: ${filteredData.length}件`;

    if (filteredData.length === 0) {
      tbody.innerHTML = '<tr><td colspan="6" style="padding: 20px; text-align: center; color: var(--text-muted); font-size: 12px;">条件に該当するデータがありません</td></tr>';
      container.querySelector('#btn-export').disabled = true;
      return;
    }

    // 最大10件まで表示
    const displayData = filteredData.slice(0, 10);
    tbody.innerHTML = displayData.map(record => {
      const worker = workers.find(w => w.id === record.作業員ID);
      const workerName = worker ? (worker.氏名 || worker.ユーザー名) : 'Unknown';
      const workDate = record.作業日 ? new Date(record.作業日).toLocaleDateString('ja-JP') : '';
      const workTime = record.作業時間 ? `${Math.floor(record.作業時間 / 60)}h${record.作業時間 % 60}m` : '';

      return `
        <tr style="border-bottom: 1px solid var(--border);">
          <td style="padding: 6px 10px; font-size: 12px; color: var(--text);">${workDate}</td>
          <td style="padding: 6px 10px; font-size: 12px; color: var(--text);">${workerName}</td>
          <td style="padding: 6px 10px; font-size: 12px; color: var(--text);">${record.作業場所 || ''}</td>
          <td style="padding: 6px 10px; font-size: 12px; color: var(--text);">${record.作業種別 || ''}</td>
          <td style="padding: 6px 10px; font-size: 12px; color: var(--text);">${workTime}</td>
          <td style="padding: 6px 10px; font-size: 12px; color: var(--text);">${record.進捗状況 || ''}</td>
        </tr>
      `;
    }).join('');

    if (filteredData.length > 10) {
      tbody.innerHTML += `<tr><td colspan="6" style="padding: 8px 10px; text-align: center; color: var(--text-muted); font-size: 11px;">他 ${filteredData.length - 10} 件...</td></tr>`;
    }

    container.querySelector('#btn-export').disabled = false;
  }

  // 条件プレビュー更新
  function updateConditionPreview() {
    const startDate = container.querySelector('#input-start-date').value;
    const endDate = container.querySelector('#input-end-date').value;
    const location = container.querySelector('#select-location').value;
    const selectedWorkers = Array.from(container.querySelector('#select-worker').selectedOptions);
    const selectedWorkItems = Array.from(container.querySelector('#select-work-item').selectedOptions);
    const includeAnomaly = container.querySelector('#check-include-anomaly').checked;
    const includeInterruption = container.querySelector('#check-include-interruption').checked;
    const format = container.querySelector('#select-format').value;

    let conditions = [];

    if (startDate || endDate) {
      const period = startDate && endDate ? `${startDate} ～ ${endDate}` : 
                    startDate ? `${startDate} 以降` : `${endDate} まで`;
      conditions.push(`期間: ${period}`);
    }

    if (location) {
      conditions.push(`作業場所: ${location}`);
    }

    if (selectedWorkers.length > 0) {
      const workerNames = selectedWorkers.map(opt => opt.textContent).join(', ');
      conditions.push(`作業員: ${workerNames}`);
    }

    if (selectedWorkItems.length > 0) {
      const itemNames = selectedWorkItems.map(opt => opt.textContent).join(', ');
      conditions.push(`作業項目: ${itemNames}`);
    }

    conditions.push(`異常値データ: ${includeAnomaly ? '含む' : '除外'}`);
    conditions.push(`中断記録: ${includeInterruption ? '含む' : '除外'}`);
    conditions.push(`出力形式: ${format.toUpperCase()}`);

    const previewElement = container.querySelector('#condition-preview');
    previewElement.innerHTML = conditions.length > 0 ? conditions.join('<br>') : '条件が設定されていません';
  }

  // CSVエクスポート
  function exportData() {
    const filteredData = filterData();
    const format = container.querySelector('#select-format').value;

    if (filteredData.length === 0) {
      alert('エクスポートするデータがありません');
      return;
    }

    // CSVヘッダー
    const headers = ['作業日', '作業員名', '作業場所', '作業種別', '作業内容', '作業時間(分)', '進捗状況', '承認状態'];

    // CSVデータ作成
    const csvData = filteredData.map(record => {
      const worker = workers.find(w => w.id === record.作業員ID);
      const workerName = worker ? (worker.氏名 || worker.ユーザー名) : '';
      const workDate = record.作業日 ? new Date(record.作業日).toLocaleDateString('ja-JP') : '';

      return [
        workDate,
        workerName,
        record.作業場所 || '',
        record.作業種別 || '',
        record.作業内容 || '',
        record.作業時間 || '',
        record.進捗状況 || '',
        record.承認状態 || ''
      ].map(field => {
        const str = String(field);
        return str.includes(',') || str.includes('\n') || str.includes('"') ? `"${str.replace(/"/g, '""')}"` : str;
      });
    });

    // CSV文字列作成
    const csvContent = '\uFEFF' + [headers, ...csvData].map(row => row.join(',')).join('\n');

    // ダウンロード
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    const url = URL.createObjectURL(blob);
    link.setAttribute('href', url);
    link.setAttribute('download', `工数記録データ_${new Date().toISOString().split('T')[0]}.${format}`);
    link.style.visibility = 'hidden';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  }

  // 条件クリア
  function clearConditions() {
    container.querySelector('#input-start-date').value = '';
    container.querySelector('#input-end-date').value = '';
    container.querySelector('#select-location').value = '';
    container.querySelector('#select-worker').selectedIndex = -1;
    container.querySelector('#select-work-item').selectedIndex = -1;
    container.querySelector('#check-include-anomaly').checked = false;
    container.querySelector('#check-include-interruption').checked = false;
    container.querySelector('#select-format').value = 'csv';

    updateConditionPreview();
    container.querySelector('#preview-tbody').innerHTML = '<tr><td colspan="6" style="padding: 20px; text-align: center; color: var(--text-muted); font-size: 12px;">条件を設定してプレビューを表示してください</td></tr>';
    container.querySelector('#data-count').textContent = '対象件数: -';
    container.querySelector('#btn-export').disabled = true;
  }

  // イベントリスナー設定
  container.querySelector('#btn-preview').addEventListener('click', () => {
    updateConditionPreview();
    updatePreview();
  });

  container.querySelector('#btn-clear').addEventListener('click', clearConditions);

  container.querySelector('#btn-save-condition').addEventListener('click', () => {
    // 条件保存機能（実装省略）
    alert('条件を保存しました');
  });

  container.querySelector('#btn-export').addEventListener('click', exportData);

  container.querySelector('#btn-back').addEventListener('click', () => {
    window.showScreen("scr-1778907145716");
  });

  // 初期化
  loadInitialData();
  updateConditionPreview();
}
